     "content": "혈중 농도를 비교해 생물학적으로 동등하다는 시험 결과가 있어요. 영일제약의 피나베린정1밀리그램과 프로페시아정1밀리그램을 건강한 성인 25명에게 1정씩 먹인 2×2 교차시험에서 생물학적으로 동등했어요.\n\n효능은 만 18~41세 남성의 남성형 탈모증 치료예요. 일반적으로 3개월 이상 먹어야 효과를 볼 수 있고, 끊으면 12개월 안에 효과가 사라져요."

