    metaDescription:
      "피나스테이트아이정5mg(피나스테리드 5mg)의 전립선비대증 적응증, 1일 1정 복용법, 발기부전·성욕감퇴 등 부작용 빈도, 28정 8,000원 기준가와 1정당 286원 가격 위치를 식약처 허가 기준으로 정리했다.",
