        content:
          "전립선비대증은 남성호르몬 테스토스테론이 DHT로 전환되면서 전립선 세포를 증식시켜 생겨요. 피나스테이트아이정5mg의 주성분 피나스테리드는 이 전환을 담당하는 5α-환원효소를 억제해 DHT 생성을 줄이고, 그 결과 전립선 크기를 줄여 소변 흐름을 개선해요. 핵심은 DHT 차단이에요.\n\n식약처 허가사항을 보면 적응증이 전립선비대증이죠. 전립선 증상 완화와 급성 요저류 위험 감소, 수술 필요성 감소가 허가 효능에 포함돼요. 탈모를 검색하다가 이 약을 알게 된 분도 많은데, 탈모 치료에는 1mg 피나스테리드로 별도 처방이 필요해요. 5mg과 1mg은 용량이 다른 별개의 허가 적응증이라, 임의로 대체하면 안 돼요.\n\n모발·탈모 관련 포럼에서 5mg을 4등분 분할해 탈모 치료에 쓰는 방법이 거론되지만, 이는 허가 범위 밖이에요. 용량 편차가 생기고 정제 코팅이 손상되면 임산부 접촉 위험도 커져요. 탈모가 목적이라면 1mg 탈모 치료 허가 제품으로 처방받는 게 안전해요. 용도를 혼동하면 안 돼요.",
