     "content": "허가된 효과에 탈모는 없어요. 피나젠정은 제일약품이 2012년 10월에 허가받은 양성전립샘비대증 치료제이고, 유앤생명과학이 위탁 제조해요. 허가정보에는 그로모정5밀리그램을 프로스카정과 28명에게 비교해 생물학적으로 동등하다는 결과가 실려 있어요.\n\n이름이 비슷한 에피나젠정은 전혀 다른 약이에요. 에피나젠정은 에피나스틴염산염 성분으로 기관지천식, 알레르기비염, 두드러기 등에 쓰는 약이니, 약 봉투의 이름을 꼭 확인하세요."
