     "content": "화이트생명과학이 2016년 3월 2일 허가받았고 영풍제약이 위탁 제조해요. 청색 사과모양 필름코팅정으로 1정 151.119mg, 각인 WH010117이에요.\n\n같은 영풍제약이 만드는 이든파마 피나드정5mg도 1정 151.119mg 청색 사과모양 정제예요. 다만 피나진정 허가사항에는 다른 제품과 원료·제조방법이 같다는 표시가 따로 없어요."
