     "content": "의약품안전나라에 올라 있는 정식 제품명은 'AG피나스테리드정(피나스테리드)(수출용)'이에요. 안국약품이 2012년 12월 3일 허가받았고, 명문제약이 위탁 제조하는 황갈색 팔각형 필름코팅정이에요. 1정 무게는 150mg이에요.\n\n제품명에 수출용이 붙어 있으니, 국내에서 처방받을 수 있는지는 약국에 먼저 물어보세요."
