    description: "레나시딘정 피나스테리드 1mg 탈모 치료제의 성분, 효능, 복용법, 부작용 정보를 제공해요.",
    heroDescription: "탈모 초기에 약을 시작하면 모발 밀도를 유지할 확률이 높아져요. 레나시딘정은 국내 제약사에서 생산하는 피나스테리드 1mg 정제로, 의사 처방 후 복용하는 전문의약품이에요.",
