   "description": "유한양행 아보테리드연질캡슐0.5밀리그램(두타스테리드)의 허가 효능(전립선비대증·만 18~50세 남성형 탈모), 아보다트 대비 발키리 가격, 탈모 임상시험",
   "heroDescription": "아보테리드는 아보다트와 같은 두타스테리드 0.5mg 연질캡슐이라, 카피약이면 효과도 같은지 궁금하죠. 허가 효능은 전립선비대증과 함께 만 18~50세 남성의 남성형 탈모 치료로 아보다트와 같아요. 그럼 효과부터 확인해야겠죠. 두타스테리드 가격과 효과부터 카피약 여부까지 차례로 알아볼게요.",
