  "두타론연질캡슐0.5mg": {
    slug: "두타론연질캡슐0.5mg",
    categorySlug: "탈모",
    datePublished: "2026-02-27",
    dateModified: "2026-04-10",
    title: "두타론연질캡슐0.5mg 가격 성분 효과 | 복용법 부작용 주의사항까지",
    h1: "두타론연질캡슐0.5mg 가격 성분 효과 | 복용법 부작용 주의사항까지",
    metaDescription: "피나스테리드 5mg 성분의 두타론연질캡슐0.5mg 복용법, 부작용, 주의사항과 가격 정보를 한눈에 정리했습니다.",
    description: "두타론연질캡슐0.5mg 두타스테리드 0.5mg 전립선비대증·탈모 치료제의 성분, 효능, 복용법, 부작용 정보를 제공해요.",
    heroDescription: "소변 문제와 함께 탈모까지 신경 쓰이는 분에게 두타스테리드가 효율적이에요. 두타론연질캡슐0.5mg은 알보젠코리아(주)의 0.5mg 정제로, 한 가지 약으로 두 가지를 관리해요.",
    products: [],
    faq: [
      { question: "두타론연질캡슐0.5mg과 피나스테리드의 차이가 뭔가요?", answer: "두타스테리드(두타론연질캡슐0.5mg)는 5alpha-환원효소 1형과 2형을 모두 억제하고, 피나스테리드는 2형만 억제해요. DHT 억제율은 두타스테리드 약 93%, 피나스테리드 65~70%예요. 반감기도 두타스테리드가 3~5주로 훨씬 길어요." },
      { question: "두타론연질캡슐0.5mg 복용 중 헌혈해도 되나요?", answer: "마지막 복용 후 최소 6개월이 지나야 헌혈이 가능해요. 반감기가 3~5주로 매우 길어서 피나스테리드(1개월 대기)보다 대기 기간이 훨씬 길어요. 임신 계획 시에도 중단 후 6개월은 피임해야 해요." },
      { question: "두타론연질캡슐0.5mg 복용을 중단하면 어떻게 되나요?", answer: "복용을 중단하면 전립선비대증 증상이 재발하고 탈모도 다시 진행될 수 있어요. 반감기가 길어서 즉시 효과가 사라지지는 않지만, 시간이 지나면 원래 상태로 돌아가요." },
    ],
    sections: [
      { title: "두타론연질캡슐0.5mg 성분은 무엇인가요?", content: "두타론연질캡슐0.5mg은 두타스테리드(Dutasteride) 0.5mg을 주성분으로 하는 정제예요. 두타스테리드는 5alpha-환원효소 1형과 2형을 모두 억제하는 이중 차단제(dual inhibitor)예요. 피나스테리드가 2형만 억제하는 것과 달리 두타스테리드는 1형까지 차단해서 혈중 DHT를 약 93%까지 감소시켜요. DHT가 더 많이 줄면 전립선 크기 감소 효과가 더 뚜렷해요.\n\n알보젠코리아(주)에서 제조한 정제 형태로, 오리지널 아보다트(GSK)와 동일 성분·함량의 제네릭이에요.\n\n정제 형태라 씹거나 분쇄하지 말고 통째로 삼켜야 해요. 반감기가 3~5주로 피나스테리드(6~8시간)보다 훨씬 길어서 체내에 오래 남아요.", ingredients: [{"type":"주성분","name":"두타스테리드","amount":"0.5mg","role":"5alpha-환원효소 1형+2형 이중 억제, DHT 약 93% 감소"},{"type":"첨가제","name":"부틸히드록시톨루엔","role":"산화 방지제"},{"type":"첨가제","name":"젤라틴 캡슐","role":"캡슐 피막"}] },
      { title: "두타론연질캡슐0.5mg 효과가 나타나려면 얼마나 걸리나요?", content: "두타론연질캡슐0.5mg은 양성 전립선비대증 치료와 성인 남성(만 18~50세)의 남성형 탈모 치료에 허가된 전문의약품이에요. 전립선비대증에서는 전립선 크기를 줄이고, 급성 요저류 위험을 낮추며, 수술 필요성을 감소시켜요. 탈모에서는 피나스테리드보다 DHT 억제율이 높아서(약 93%) 더 강한 탈모 억제 효과를 보여줘요.\n\n전립선비대증 효과는 6개월 이상, 탈모 효과는 3~6개월 이상 복용해야 판단할 수 있어요. 복용을 중단하면 두 가지 효과 모두 점차 사라져요. 반감기가 3~5주로 길어서 중단 후에도 체내에 오래 남아요.\n\n피나스테리드 1mg 정제와 비교하면 DHT 억제 범위가 넓고(1형+2형 vs 2형만) 억제율이 더 높지만, 성기능 부작용 발생률도 약간 높을 수 있어요. 원형탈모, 여성형 탈모에는 효과가 없어요." },
      { title: "두타론연질캡슐0.5mg 복용법은 어떻게 되나요?", content: "1일 1회 1캡슐(두타스테리드 0.5mg)을 식사와 무관하게 복용해요. 두타론연질캡슐0.5mg은 정제 형태라 씹거나 분쇄하지 말고 통째로 삼켜야 해요. 매일 같은 시간에 복용하면 혈중 농도가 안정적으로 유지돼요.\n\n복용을 잊었다면 생각난 즉시 1캡슐을 먹고, 다음 복용 시간이 가까우면 건너뛰세요. 한 번에 2캡슐을 먹으면 안 돼요. 반감기가 3~5주로 매우 길어서 1회 누락이 큰 영향을 주지는 않지만, 규칙적 복용이 원칙이에요.\n\n피나스테리드 정제와 달리 두타스테리드는 반감기가 길어서 중단 후에도 체내에 오래 남아요. 임신 계획이 있다면 복용 중단 후 최소 6개월은 피임해야 해요. 헌혈도 마지막 복용 후 6개월이 지나야 가능해요." },
      { title: "두타론연질캡슐0.5mg 부작용은 어떤 게 있나요?", content: "두타론연질캡슐0.5mg 복용 시 가장 흔한 부작용은 발기부전, 성욕 감퇴, 사정 장애, 사정량 감소예요. 피나스테리드보다 DHT 억제율이 높아서 성기능 부작용 발생률도 약간 높을 수 있어요. 복용 초기에 많이 나타나고 시간이 지나면서 줄어드는 경향이 있어요.\n\n유방 비대, 유방 압통이 드물게 보고됐어요. 우울증, 불안, 자살 충동 같은 정신과적 증상도 나타날 수 있어서 기분 변화가 지속되면 즉시 의사와 상담하세요.\n\n과민반응(발진, 가려움, 두드러기, 혈관부종), 탈모증(역설적 탈모), 어지럼, 두통도 드물게 나타나요. 반감기가 3~5주로 길어서 부작용이 나타나도 약물이 체내에서 빠져나가는 데 시간이 오래 걸려요. PSA 수치를 약 50% 낮추므로 전립선암 검진 전 복용 사실을 반드시 알리세요." },
      { title: "두타론연질캡슐0.5mg 주의사항은 무엇인가요?", content: "두타론연질캡슐0.5mg은 여성과 소아에게 절대 투여하면 안 돼요. 임부 또는 임신 가능성이 있는 여성은 캡슐 내용물에 접촉하면 안 되고, 새는 캡슐도 만지면 안 돼요. 두타스테리드는 피부를 통해 흡수되어 남성 태아 외부 생식기에 이상을 줄 수 있어요.\n\n반감기가 3~5주로 매우 길기 때문에 헌혈은 마지막 복용 후 최소 6개월이 지나야 가능해요. 피나스테리드(1개월)보다 대기 기간이 훨씬 길어요. 임신 계획이 있다면 중단 후 6개월은 피임이 필요해요.\n\nPSA 수치를 약 50% 낮추므로 전립선암 검진 전 복용 사실을 알리세요. 간 기능 이상 환자는 용량이 확립되지 않았으니 의사와 상의하세요. 다른 5alpha-환원효소 억제제(피나스테리드)와 동시 복용은 금지예요." },
      { title: "두타론연질캡슐0.5mg 보관할 때 주의할 점은 무엇인가요?", content: "두타론연질캡슐0.5mg은 밀폐 용기에 넣어 습기를 피하고 15~30도 실온에서 보관해요. 욕실이나 주방처럼 습도가 높고 온도 변화가 심한 곳은 피하세요. 직사광선이 닿지 않는 서랍이나 약 보관함이 좋아요.\n\n임산부가 있는 가정에서는 접근이 차단된 별도 공간에 보관하는 게 안전해요. 정제는 분쇄하지 말고 원형 그대로 둬야 해요. 어린이 손이 닿지 않는 높은 곳에 두는 것도 기본이에요.\n\n유통기한이 지난 약은 약국의 폐의약품 수거함에 반납하세요. 포장이 변형되었거나 약의 색·냄새가 이상하면 복용하지 말고 폐기하세요. 다른 약과 한 통에 섞어 보관하면 오용 사고가 생길 수 있어요." },
    ],
  },
